import React, { useState } from "react";

export default function Exam() {

const questions=[

{

question:"Java is ?",

options:["Language","Database","Browser","OS"],

answer:"Language"

},

{

question:"React is ?",

options:["Framework","Library","Database","OS"],

answer:"Library"

},

{

question:"HTML stands for ?",

options:[

"Hyper Text Markup Language",

"High Text Language",

"Hyper Tool Markup",

"None"

],

answer:"Hyper Text Markup Language"

}

];

const [answers,setAnswers]=useState({});

const [score,setScore]=useState(null);

const handleChange=(index,value)=>{

setAnswers({

...answers,

[index]:value

});

};

const submitExam=()=>{

let marks=0;

questions.forEach((q,index)=>{

if(answers[index]===q.answer){

marks++;

}

});

setScore(marks);

};

return(

<div style={{

padding:"40px",

background:"#f3f4f6",

minHeight:"100vh"

}}>

<h1

style={{

textAlign:"center",

color:"#2563eb"

}}

>

📝 Online Exam

</h1>

{

questions.map((q,index)=>(

<div

key={index}

style={{

background:"white",

padding:"20px",

marginTop:"20px",

borderRadius:"15px"

}}

>

<h3>

Q{index+1}.

{q.question}

</h3>

{

q.options.map((opt,i)=>(

<div key={i}>

<input

type="radio"

name={index}

value={opt}

onChange={(e)=>

handleChange(

index,

e.target.value

)

}

/>

{" "}

{opt}

</div>

))

}

</div>

))

}


<button

onClick={submitExam}

style={{

marginTop:"30px",

padding:"12px 25px",

background:"#2563eb",

color:"white",

border:"none",

borderRadius:"8px",

cursor:"pointer"

}}

>

Submit Exam

</button>


{

score!==null && (

<h2

style={{

marginTop:"20px",

color:"green"

}}

>

✅ Your Score :

{score}

/

{questions.length}

</h2>

)

}

</div>

)

}
